sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    if (g_form.getValue('category') == 'sla') {
       g_form.setDisplay('duration', true);
        g_form.setMandatory('duration', true);
		g_form.setDisplay('unique_id',true);
		g_form.setMandatory('unique_id',true);
    }else{
		g_form.setMandatory('duration',false);
        g_form.setDisplay('duration', false);
		g_form.setMandatory('unique_id',false);
		g_form.setDisplay('unique_id',false);
	}
}
